def _proof_level_count(index: int, size: int) -> int:
    """Sibling count an inclusion proof for ``index`` within ``size`` entries needs."""
    count = 0
    position = index
    width = size
    while width > 1:
        if position % 2 == 1 or position + 1 < width:
            count += 1
        position //= 2
        width = (width + 1) // 2
    return count

